#include "SpeechPostgresTasks.h"
namespace webserver::function3 {
void SpeechPostgresTasks::enqueue(Id announcement,std::string text,Milliseconds expires){sql_.requireTransaction();sql_.query("INSERT INTO announcement_audio(announcement_id,voice,source_text,expires_ms) VALUES($1,'zf_001',$2,$3),($1,'zm_009',$2,$3) ON CONFLICT DO NOTHING",{std::to_string(announcement),std::move(text),std::to_string(expires)});}
std::optional<SpeechJob>SpeechPostgresTasks::claim(){SqlRows rows;sql_.transact([&]{sql_.query("UPDATE announcement_audio SET state='failed',lease_until=NULL,last_error='announcement expired' WHERE state='pending' AND expires_ms<=extract(epoch FROM CURRENT_TIMESTAMP)*1000 AND (lease_until IS NULL OR lease_until<CURRENT_TIMESTAMP)");rows=sql_.query("WITH picked AS(SELECT announcement_id,voice FROM announcement_audio WHERE state='pending' AND available_at<=CURRENT_TIMESTAMP AND (lease_until IS NULL OR lease_until<CURRENT_TIMESTAMP) AND expires_ms>extract(epoch FROM CURRENT_TIMESTAMP)*1000 ORDER BY announcement_id,voice FOR UPDATE SKIP LOCKED LIMIT 1) UPDATE announcement_audio a SET lease_until=CURRENT_TIMESTAMP+INTERVAL '120 seconds',attempts=attempts+1 FROM picked WHERE a.announcement_id=picked.announcement_id AND a.voice=picked.voice RETURNING a.announcement_id,a.source_text,a.voice,a.expires_ms");});if(rows.empty())return {};auto&r=rows[0];return SpeechJob{std::stoull(r[0]),r[1],r[2],std::stoll(r[3])};}
void SpeechPostgresTasks::complete(const SpeechJob&j,std::string key){sql_.transact([&]{sql_.query("UPDATE announcement_audio SET state='ready',cache_key=$3,lease_until=NULL,last_error='' WHERE announcement_id=$1 AND voice=$2",{std::to_string(j.announcement),j.voice,std::move(key)});if(events_){auto now=std::stoll(sql_.query("SELECT floor(extract(epoch FROM clock_timestamp())*1000)::bigint")[0][0]);events_->appendEvent({0,"announcement.audio.ready","announcement.audio."+j.voice,j.announcement,1,{{"announcementId",std::to_string(j.announcement)},{"voice",j.voice}},now});}});}
void SpeechPostgresTasks::failed(const SpeechJob&j){sql_.transact([&]{sql_.query("UPDATE announcement_audio SET state=CASE WHEN attempts>=3 THEN 'failed' ELSE 'pending' END,lease_until=NULL,last_error='speech worker failed',available_at=CURRENT_TIMESTAMP+make_interval(secs=>attempts*5) WHERE announcement_id=$1 AND voice=$2",{std::to_string(j.announcement),j.voice});});}
SpeechAudio SpeechPostgresTasks::audio(Id announcement,std::string voice)const{auto rows=sql_.query("SELECT state,cache_key FROM announcement_audio WHERE announcement_id=$1 AND voice=$2",{std::to_string(announcement),std::move(voice)});return rows.empty()?SpeechAudio{"pending",""}:SpeechAudio{rows[0][0],rows[0][1]};}
}
